import sys
sys.setrecursionlimit(500000)

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
    except StopIteration:
        return

    if n == 1:
        print("1")
        return

    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u = int(next(iterator))
        v = int(next(iterator))
        adj[u].append(v)
        adj[v].append(u)

    parent = [0] * (n + 1)
    order = []
    stack = [1]
    visited = [False] * (n + 1)
    visited[1] = True

    while stack:
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                stack.append(v)

    subtree_size = [1] * (n + 1)
    for u in reversed(order):
        p = parent[u]
        if p != 0:
            subtree_size[p] += subtree_size[u]

    max_comp = [0] * (n + 1)
    threshold = n // 2

    for u in range(1, n + 1):
        current_max = 0
        for v in adj[u]:
            if v == parent[u]:
                comp_size = n - subtree_size[u]
            else:
                comp_size = subtree_size[v]
            if comp_size > current_max:
                current_max = comp_size
        max_comp[u] = current_max

    def can_make_centroid(u):
        if max_comp[u] <= threshold:
            return True

        largest_comp = 0
        second_largest_comp = 0
        largest_comp_node = -1

        for v in adj[u]:
            if v == parent[u]: 
                sz = n - subtree_size[u]
            else:
                sz = subtree_size[v]

            if sz > largest_comp:
                second_largest_comp = largest_comp
                largest_comp = sz
                largest_comp_node = v
            elif sz > second_largest_comp:
                second_largest_comp = sz

        if largest_comp > threshold:
            rest = n - largest_comp
            if rest <= threshold:
                if largest_comp_node == parent[u]:
                    return False
                root_of_largest = largest_comp_node
                p = root_of_largest
                while parent[p] != u:
                    p = parent[p]

                sz_below = subtree_size[root_of_largest]
                sz_above = n - sz_below

                if sz_above <= threshold and sz_below <= threshold:
                    return True
                return False
            else:
                return False

        return True

    results = []
    for i in range(1, n + 1):
        if can_make_centroid(i):
            results.append("1")
        else:
            results.append("0")

    print(" ".join(results))

if __name__ == "__main__":
    main()
